// ── Validate & normalise form submission ──────────────────────────
const item = $input.first();
const data = item.json;

const fullName   = (data['Full Name'] || '').trim();
const email      = (data['Email Address'] || '').trim();
const phone      = (data['Phone Number'] || '').trim();
const jobRole    = (data['Job Role'] || '').trim();
const resumeFile = data['Resume (PDF only)'];

const errors = [];

if (!fullName) errors.push('Full Name is missing.');
if (!email || !/^[^@]+@[^@]+\.[^@]+$/.test(email))
  errors.push('Email is missing or invalid.');
if (!phone) errors.push('Phone Number is missing.');
if (!jobRole) errors.push('Job Role is missing.');

if (errors.length) {
  throw new Error(errors.join(' | '));
}

const applicationId =
  'APP-' + Date.now() + '-' + Math.random().toString(36).substring(2,7).toUpperCase();

return [{
  json: {
    applicationId,
    fullName,
    email,
    phone,
    jobRole,
    resumeFile,
    submittedAt: new Date().toISOString()
  },
  binary: item.binary   
}];

// ── Match the submitted Job Role to its Job Description row ──────

const validatedData = $('Validate & Normalise Input').first();
const data = validatedData.json;
const jobRole = data.jobRole;

// Get all rows from Google Sheet
const allRows = $input.all();

// Find the matching Job Title
const matchedRow = allRows.find(
  row =>
    (row.json['Job Title'] || '')
      .trim()
      .toLowerCase() === jobRole.trim().toLowerCase()
);

if (!matchedRow) {
  throw new Error(`No Job Description found in Google Sheet for role: "${jobRole}"`);
}

const jd = matchedRow.json;

// Return JSON + Binary
return [
  {
    json: {
      ...data,
      jobTitle: jd['Job Title'] || jobRole,
      jobDescription: jd['Job Description'] || '',
      requiredSkills: jd['Required Skills'] || '',
      minimumExperience: jd['Minimum Experience'] || '',
      preferredQualifications: jd['Preferred Qualifications'] || '',
    },
    binary: validatedData.binary,
  },
];

// ── Extract binary resume data for PDF parsing ───────────────────
const item = $input.first();
const resumeField = item.json.resumeFile;

// n8n stores uploaded files as binary data referenced by key
// The form trigger stores file uploads in item.binary
let binaryKey = null;

if (item.binary) {
  const binaryKeys = Object.keys(item.binary);
  // Find the key that corresponds to the resume
  binaryKey = binaryKeys.find(k => k.toLowerCase().includes('resume') || k.toLowerCase().includes('pdf')) || binaryKeys[0];
}

if (!binaryKey && !resumeField) {
  throw new Error('Resume binary data not found. Ensure the form uploaded the PDF correctly.');
}

return [{
  json: item.json,
  binary: item.binary || {}
}];

// Merge extracted resume text with job data

const extractedItem = $input.first();
const accumulatedData = $('Match Job Description').first().json;

// Get extracted resume text
let resumeText = extractedItem.json.text || "";

// Clean special characters so JSON doesn't break
resumeText = resumeText
  .replace(/\r/g, " ")
  .replace(/\n/g, "\\n")
  .replace(/\t/g, " ")
  .replace(/"/g, '\\"')
  .trim();

// Count words
const words = resumeText.split(/\s+/);

return [
  {
    json: {
      ...accumulatedData,
      resumeText,
      resumeWordCount: words.length
    }
  }
];

// ── Parse & validate the AI response ─────────────────────────────
const aiResponse = $input.first().json;
const inputData  = $('Merge Resume Text & Job Data').first().json;

let rawText = '';
try {
  rawText = aiResponse.candidates[0].content.parts[0].text || '';
} catch (e) {
  throw new Error('AI API returned an unexpected response structure: ' + JSON.stringify(aiResponse).substring(0, 300));
}

// Strip markdown fences if Gemini wraps in them despite our instruction
let cleanText = rawText.trim();
if (cleanText.startsWith('```')) {
  cleanText = cleanText.replace(/^```[a-z]*\n?/i, '').replace(/```\s*$/,'').trim();
}

let parsed;
try {
  parsed = JSON.parse(cleanText);
} catch (e) {
  throw new Error('Failed to parse AI JSON response. Raw output: ' + cleanText.substring(0, 500));
}

// --- Validate required fields ---
const required = ['scores','overallScore','verdict','strengths','weaknesses','missingSkills','aiSummary','recommendedInterviewQuestions'];
for (const field of required) {
  if (parsed[field] === undefined) {
    throw new Error(`AI response missing required field: "${field}"`);
  }
}

// --- Enforce verdict based on score (safety net) ---
const score = Number(parsed.overallScore);
let verdict = parsed.verdict;
if (score >= 70)      verdict = 'Shortlisted';
else if (score >= 50) verdict = 'Human Review';
else                   verdict = 'Rejected';

// --- Verdict emoji for readability ---
const verdictEmoji = verdict === 'Shortlisted' ? '✅' : verdict === 'Human Review' ? '🔶' : '❌';

return [{
  json: {
    ...inputData,
    scores: parsed.scores,
    overallScore: score,
    verdict,
    verdictEmoji,
    strengths:    Array.isArray(parsed.strengths)    ? parsed.strengths.join('\n• ')    : parsed.strengths,
    weaknesses:   Array.isArray(parsed.weaknesses)   ? parsed.weaknesses.join('\n• ')   : parsed.weaknesses,
    missingSkills: Array.isArray(parsed.missingSkills) ? parsed.missingSkills.join(', ') : parsed.missingSkills,
    aiSummary:    parsed.aiSummary,
    interviewQuestions: Array.isArray(parsed.recommendedInterviewQuestions)
      ? parsed.recommendedInterviewQuestions.join('\n')
      : parsed.recommendedInterviewQuestions,
    scoringRationale: parsed.scoringRationale || '',
    processedAt: new Date().toISOString()
  }
}];

